// truncate-tooltip.directive.ts
import { AfterViewInit, Directive, ElementRef, HostListener, Input } from '@angular/core';
import { MatTooltip } from '@angular/material/tooltip';

@Directive({
  selector: '[truncateTooltip]',
  standalone: true,
  hostDirectives: [{
    directive: MatTooltip,
    inputs: ['matTooltipPosition', 'matTooltipShowDelay', 'matTooltipHideDelay']
  }]
})
export class TruncateTooltipDirective implements AfterViewInit {
  @Input() tooltipText?: string;
  @Input() truncateClass?: string;

  constructor(
    private el: ElementRef,
    private tooltip: MatTooltip
  ) {}

  ngAfterViewInit() {
    if (this.truncateClass) {
      requestAnimationFrame(() => this.updateTruncateClass());
    }
  }

  @HostListener('mouseenter')
  onMouseEnter(): void {
    const element = this.el.nativeElement;
    const isTruncated = element.scrollWidth > element.clientWidth ||
                        element.scrollHeight > element.clientHeight;
    if (isTruncated) {
      this.tooltip.message = this.tooltipText || element.textContent?.trim();
      this.tooltip.disabled = false;
    } else {
      this.tooltip.disabled = true;
    }
    if (this.truncateClass) {
      this.updateTruncateClass();
    }
  }

  private updateTruncateClass(): void {
    const element = this.el.nativeElement;
    const isTruncated = element.scrollWidth > element.clientWidth ||
                        element.scrollHeight > element.clientHeight;
    if (isTruncated) {
      element.classList.add(this.truncateClass);
    } else {
      element.classList.remove(this.truncateClass);
    }
  }
}
