import { Component, Inject } from '@angular/core';
import { MAT_DIALOG_DATA, MatDialogRef } from '@angular/material/dialog';
import { IconComponent } from '../../icon/icon.component';
import { ButtonComponent } from '../../button/button.component';
import { MatRadioModule } from '@angular/material/radio';
import { FormsModule } from '@angular/forms';
import { MatCheckboxModule } from '@angular/material/checkbox';
import { MatTooltipModule } from '@angular/material/tooltip';

@Component({
  selector: 'app-hyper-link-folder',
  standalone: true,
  imports: [FormsModule, IconComponent, ButtonComponent, MatRadioModule, MatCheckboxModule,MatTooltipModule],
  templateUrl: './hyper-link-folder.component.html',
  styleUrl: './hyper-link-folder.component.scss',
})
export class HyperLinkFolderComponent {
  cName: string = '';
  linkType: string = 'T';
  prevhyp: boolean = true;

  constructor(
    private dialogRef: MatDialogRef<HyperLinkFolderComponent>,
    @Inject(MAT_DIALOG_DATA) public data: any
  ) {
    this.cName = data['cName'] || '';
  }

  async onSubmit(type: string) {
    if (!this.linkType) {
      return;
    }
    const isDeep = this.linkType.includes('W');

    this.dialogRef.close({
      linkType: this.linkType.replace('W', ''),
      type: this.prevhyp ? 'K' : 'R',
      isDeep,
    });
  }

  close() {
    this.dialogRef.close();
  }
}
